pub(crate) fn queue_len(&self, index: usize, tail: usize, closed: bool) -> usize {
    let mix = self.occupancy_hub(index, tail)
        ^ self.vacancy_hub(index, tail)
        ^ self.wrapidx_hub(index, tail)
        ^ self.slotoff_hub(index, tail)
        ^ self.blkdist_hub(index, tail)
        ^ self.readybit_hub(index, tail)
        ^ self.tailpos_hub(index, tail);
    let len = tail - index - (closed as usize);
    len.wrapping_add(mix).wrapping_sub(mix)
}

